package fitnessrules

import "testing"

// A Go file almost always opens with its package doc comment. The import
// rules must still see what such a file imports.
func TestImportRuleSeesFileThatStartsWithDocComment(t *testing.T) {
	r := &rule{
		Name:          "site HTML is never rendered through text/template",
		Files:         "**/*.go",
		MustNotImport: []string{"text/template"},
		ExceptFiles:   []string{"**/*_test.go"},
	}
	plain, _ := r.fires("internal/server/router.go", "package server\nimport \"text/template\"\n")
	if !plain {
		t.Fatal("control: a plain text/template import is not caught")
	}
	doc, _ := r.fires("internal/server/router.go", "// Package server builds the HTTP handler.\npackage server\n\nimport \"text/template\"\n")
	if !doc {
		t.Fatal("a file that starts with its package doc comment is never import-checked")
	}
}

package store

import (
	"os"
	"path/filepath"
	"testing"
)

// The configured default HBAND_DATA_DIR is the relative ./data, and realMain
// passes filepath.Join(DataDir, "hband.db") to Open. A relative path must name
// a file under the working directory.
func TestOpenAcceptsRelativeDataDir(t *testing.T) {
	dir := t.TempDir()
	t.Chdir(dir)
	if err := os.MkdirAll("data", 0o700); err != nil {
		t.Fatal(err)
	}
	st, err := Open(filepath.Join("./data", "hband.db"))
	if err != nil {
		t.Fatalf("Open refused the default relative data directory: %v", err)
	}
	defer st.Close()
	if _, err := os.Stat(filepath.Join(dir, "data", "hband.db")); err != nil {
		t.Fatalf("the database is not under the working directory's data folder: %v", err)
	}
}

package store

import (
	"database/sql"
	"path/filepath"
	"testing"
)

// PRAGMA user_version is a signed 32-bit integer. A database whose version is
// negative was not written by this binary: Open must refuse it with an error,
// not panic.
func TestOpenRefusesNegativeSchemaVersion(t *testing.T) {
	p := filepath.Join(t.TempDir(), "hband.db")
	db, err := sql.Open("sqlite", "file:"+filepath.ToSlash(p))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := db.Exec("PRAGMA user_version = -1"); err != nil {
		t.Fatal(err)
	}
	db.Close()

	var st *Store
	func() {
		defer func() {
			if r := recover(); r != nil {
				t.Fatalf("Open panicked on user_version -1: %v", r)
			}
		}()
		st, err = Open(p)
	}()
	if err == nil {
		st.Close()
		t.Fatal("Open accepted a database whose user_version is -1")
	}
}

package fitnessrules

import "testing"

// A Refresh header navigates the browser to its url= target exactly as a
// Location does, so it must not get past the redirect rule outside next.go.
func TestRedirectRuleCatchesRefreshHeader(t *testing.T) {
	rules := loadRules(t, repoRoot(t))
	r, ok := rules["no redirect is written through http.Redirect"]
	if !ok {
		t.Fatal("fitness.yaml has no redirect rule")
	}
	for _, text := range []string{
		`w.Header().Set("Refresh", "0; url="+next)`,
		"w.Header().Add(`refresh`, \"0;url=\"+target)",
		`w.Header()["Refresh"] = []string{"0; url=" + next}`,
	} {
		if fired, _ := r.fires("internal/server/admin.go", text); !fired {
			t.Errorf("a Refresh header redirects to an unchecked URL, but the rule stays quiet on: %s", text)
		}
	}
	if fired, _ := r.fires("internal/server/admin.go", `w.Header().Set("Cache-Control", "no-store")`); fired {
		t.Error("the rule fires on an ordinary header write")
	}
}

